/*--------------------------------------------------------------------------*/

void wake_set_timeout1( UInt16 timeout_in_ms )
{
    wake_init();

    ATOMIC(wake_vars.timeout1 = timeout_in_ms/10);
}

/*--------------------------------------------------------------------------*/

void wake_set_timeout2( UInt16 timeout_in_ms )
{
    wake_init();

    ATOMIC(wake_vars.timeout2 = timeout_in_ms/10);
}

/*--------------------------------------------------------------------------*/
#if USE_TIMESTAMP == 1

void wake_set_timeout( UInt16 timeout_in_ms )
{
    wake_init();

    ATOMIC(wake_vars.timeout = timeout_in_ms/10);
}
#endif

